window.RP_SESSION={"id":"S-7c20f00d9a19","messages":[{"id":"RP-II-0080987","time":"2026-04-12T14:04:00+09:00","room":"RP II","name":"엘런 파드메","profile":"엘런 파드메","identity":"reviewed","type":"dialogue","body":"골기아. 낮. 시일을 채 가늠할 수 없는 인간들의 왕국의 푸른 하늘 위로 해가 머리끝에 와닿았을 즈음이 되어서야, 엘런은 간이 대장간에서 감고 있던 눈을 떴다. 수리가 필요하나 값비싼 대장장이들의 손을 빌려야 할 정도까진 아니한 장비들의 손질을 시도하는 모험가들을 위해 길드 건물 근처에 마련된 작은 공간답게, 내부의 환경은 그리 풍족해 보이지 않았다. 이는 과거, 머나먼 고향에서 엘런이 가업과 함께 아버지에게 물려받기로 예정되어 있었던 대장간—「불길」과 비교하여도 상대적으로 약소한 수준이었다. 부정할 순 없었다. 그곳은 지겨울지언정 넓긴 했으니까.\n\n좁은 규모에 비례하듯, 길드의 간이 대장간은 엘런에게 있어 만족스러울 정도로 근사한 공간만큼은 절대 아니었다. 숯덩이들과 더불어 그을린 화덕의 크기는 작았고, 모루는 웬 솜씨 없는 놈이 잘못 두들기다 일을 그르치고 말았는지 귀퉁이가 보기 흉하게 닳아 있었다. 불의 온도를 조절하기 위해 공기를 불어넣어 줄 풀무는 애초에 있지도 않았고, 심","characters":["P-78d86f34eb28"]},{"id":"RP-II-0080988","time":"2026-04-12T14:04:00+09:00","room":"RP II","name":"엘런 파드메","profile":"엘런 파드메","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-78d86f34eb28"]},{"id":"RP-II-0080989","time":"2026-04-12T14:04:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
